@supports ((-moz-appearance:none)) {
  .showScrollbar:root * { scrollbar-color: var(--scrollbar-color-bg-default) transparent; scrollbar-width: thin; }
}
:root.showScrollbar { scrollbar-gutter: stable; }
.showScrollbar:root ::-webkit-scrollbar-track { background: var(--color-background-base-primary); }
:root:not(.showScrollbar) body::-webkit-scrollbar { display: none; }
:root:not(.showScrollbar) ::-webkit-scrollbar-track { background: 0px 0px; }
::-webkit-scrollbar { width: 11px; height: 11px; }
::-webkit-scrollbar-thumb { border-radius: var(--rounding-max); background-clip: content-box; background-color: var(--scrollbar-color-bg-default); border: 4px solid rgba(0, 0, 0, 0); transition: 0.2s; }
::-webkit-scrollbar-thumb:hover { background-color: var(--scrollbar-color-bg-hover); border: 2px solid rgba(0, 0, 0, 0); }
::-webkit-scrollbar-button { display: none; }
::-webkit-scrollbar-corner { display: none; }
.lockScroll { touch-action: none; overflow: hidden; }
:root { -webkit-font-smoothing: antialiased; }

